function chartTime(value){
  if(typeof value==='number'||/^\d+(\.\d+)?$/.test(String(value))){const numeric=Number(value);return Math.floor(numeric>1e12?numeric/1000:numeric)}
  const parsed=Date.parse(value);return Number.isFinite(parsed)?Math.floor(parsed/1000):null;
}
function mapCandlesToLightweight(bars){
  const mapped=(bars||[]).map(bar=>({time:chartTime(bar.timestamp??bar.time),open:Number(bar.open),high:Number(bar.high),low:Number(bar.low),close:Number(bar.close)})).filter(bar=>bar.time!=null&&['open','high','low','close'].every(key=>Number.isFinite(bar[key]))).sort((a,b)=>a.time-b.time);
  return mapped.filter((bar,index)=>!index||bar.time!==mapped[index-1].time);
}
function mapVolumeToLightweight(bars){
  return (bars||[]).filter(bar=>bar.volume!=null&&bar.volume!=='').map(bar=>({time:chartTime(bar.timestamp??bar.time),value:Number(bar.volume),color:Number(bar.close)>=Number(bar.open)?'rgba(36, 211, 149, .38)':'rgba(255, 91, 111, .38)'})).filter(bar=>bar.time!=null&&Number.isFinite(bar.value)&&bar.value>=0).sort((a,b)=>a.time-b.time);
}
function selectedChartData(data,selectedFrame){
  const series=data.chart_timeframes||{},fallback=(data.chart_points||[]).map(p=>({timestamp:p.timestamp,open:p.close,high:p.close,low:p.close,close:p.close}));
  const available=chartFrames.filter(frame=>(series[frame]||[]).length>1),frame=(selectedFrame&&available.includes(selectedFrame)?selectedFrame:null)||data.chart_default_timeframe||available[0];
  return {series,available,frame,bars:series[frame]||fallback};
}
function chartToolbar(series,frame){return `<div class="chart-toolbar"><div><p class="eyebrow">MARKET CHART</p><strong>${safe(frame||'Price history')}</strong></div><div class="timeframe-buttons" role="group" aria-label="Chart timeframe">${chartFrames.map(item=>`<button type="button" data-chart-frame="${item}" class="${item===frame?'active':''}" ${series[item]?.length>1?'':'disabled'}>${item}</button>`).join('')}</div></div>`}
function priceChart(data,selectedFrame){
  const {series,frame,bars}=selectedChartData(data,selectedFrame),candles=mapCandlesToLightweight(bars);
  const buttons=chartToolbar(series,frame);
  if(candles.length<2)return `<div class="price-chart">${buttons}<div class="chart-unavailable"><span>Chart unavailable</span><small>Candle history is not available for this asset.</small></div></div>`;
  return `<div class="price-chart lightweight-price-chart" data-active-frame="${safe(frame)}">${buttons}<div class="advanced-chart-shell"><div class="lightweight-chart-container" role="img" aria-label="${safe(frame)} interactive candlestick chart"></div><div class="lightweight-ohlc" role="status" aria-live="polite"></div></div><div class="chart-fallback" hidden>${svgPriceChart(data,frame)}<p class="fallback-note">Advanced chart unavailable; showing basic chart.</p></div><div class="chart-level-legend" aria-label="Chart price levels"></div><a class="chart-attribution" href="https://www.tradingview.com/" target="_blank" rel="noopener noreferrer">Charts by TradingView</a></div>`;
}
const chartLevelNames=[['Support'],['Resistance'],['Stop'],['Take profit'],['Current']];
function priceLineConfiguration(data,bars){
  const values=chartLevels(data),holding=data.risk_plan?.has_active_trade_setup===false||['HOLD','WATCH','AVOID'].includes(String(data.signal?.side).toUpperCase());
  const levels=[[holding?'Watch below':'Support',values.support,'#24d395'],[holding?'Watch above':'Resistance',values.resistance,'#f7bd52'],['Stop',values.stop_loss,'#ff5b6f'],['Take profit',values.take_profit,'#559cff'],['Current price',values.current_price,'#d8e5ef']];
  const prices=mapCandlesToLightweight(bars).flatMap(bar=>[bar.high,bar.low]),low=Math.min(...prices),high=Math.max(...prices),range=high-low||Math.abs(high)||1;
  return levels.map(([title,value,color])=>({title,price:Number(value),color,lineWidth:title==='Current'?2:1,lineStyle:title==='Current'?0:2,axisLabelVisible:true,inScale:Number.isFinite(Number(value))&&Number(value)>=low-range*.35&&Number(value)<=high+range*.35})).filter(level=>Number.isFinite(level.price));
}
function chartLevels(data){const plan=data.risk_plan||{},active=plan.has_active_trade_setup!==false&&!['HOLD','WATCH','AVOID'].includes(String(data.signal?.side).toUpperCase());return {support:data.key_levels?.support,resistance:data.key_levels?.resistance,stop_loss:active?(plan.stop_loss??data.key_levels?.stop_loss):null,take_profit:active?(plan.take_profit??data.key_levels?.take_profit):null,current_price:data.live_price??data.market?.price}}
function showSvgFallback(container){
  container.querySelector('.advanced-chart-shell')?.setAttribute('hidden','');const fallback=container.querySelector('.chart-fallback');if(fallback){fallback.hidden=false;bindChartHover(fallback)}
}
async function mountLightweightChart(container,data,selectedFrame){
  const target=container.querySelector('.lightweight-chart-container');if(!target)return;
  try{
    const LC=await loadLightweightCharts();if(!target.isConnected)return;
    const {bars}=selectedChartData(data,selectedFrame),candles=mapCandlesToLightweight(bars),volume=mapVolumeToLightweight(bars);
    const chart=LC.createChart(target,{autoSize:false,layout:{background:{type:'solid',color:'#071722'},textColor:'#8fa7b9',fontFamily:'Inter,system-ui,sans-serif'},grid:{vertLines:{color:'#122a39'},horzLines:{color:'#122a39'}},crosshair:{mode:LC.CrosshairMode.Normal},rightPriceScale:{visible:true,borderColor:'#294252',scaleMargins:{top:.08,bottom:volume.length?.23:.08}},timeScale:{visible:true,borderColor:'#294252',timeVisible:true,secondsVisible:false,rightOffset:5,barSpacing:8},handleScroll:true,handleScale:true});
    const candleSeries=chart.addCandlestickSeries({upColor:'#24d395',downColor:'#ff5b6f',borderUpColor:'#24d395',borderDownColor:'#ff5b6f',wickUpColor:'#24d395',wickDownColor:'#ff5b6f',priceLineVisible:false,lastValueVisible:true,priceFormat:chartPriceFormat(candles.at(-1)?.close??data.live_price)});candleSeries.setData(candles);
    if(volume.length){const volumeSeries=chart.addHistogramSeries({priceFormat:{type:'volume'},priceScaleId:'volume',lastValueVisible:false,priceLineVisible:false});volumeSeries.priceScale().applyOptions({scaleMargins:{top:.78,bottom:0}});volumeSeries.setData(volume)}
    const levels=priceLineConfiguration(data,bars),legend=container.querySelector('.chart-level-legend');
    levels.filter(level=>level.inScale).forEach(level=>candleSeries.createPriceLine(level));legend.innerHTML=levels.map(level=>`<span style="--level-color:${level.color}"><i></i>${safe(level.title)} <b>${price(level.price)}</b>${level.inScale?'':' · off scale'}</span>`).join('');
    const ohlc=container.querySelector('.lightweight-ohlc'),renderOhlc=bar=>{ohlc.innerHTML=bar?`<span>O <b>${price(bar.open)}</b></span><span>H <b>${price(bar.high)}</b></span><span>L <b>${price(bar.low)}</b></span><span>C <b>${price(bar.close)}</b></span>`:''};renderOhlc(candles.at(-1));
    chart.subscribeCrosshairMove(param=>renderOhlc(param.seriesData.get(candleSeries)||candles.at(-1)));
    const resize=()=>chart.applyOptions({width:target.clientWidth,height:Math.max(300,Math.min(440,target.clientWidth*.54))});resize();const observer=new ResizeObserver(resize);observer.observe(target);chart.timeScale().fitContent();
    container._chartCleanup=()=>{observer.disconnect();chart.remove()};
  }catch(error){showSvgFallback(container)}
}
function bindChartHover(container){
  const stage=container.querySelector('.chart-stage'),svg=stage?.querySelector('svg'),tooltip=stage?.querySelector('.chart-tooltip'),candles=[...(svg?.querySelectorAll('[data-candle-index]')||[])];
  if(!stage||!svg||!tooltip||!candles.length)return;
  const xLine=svg.querySelector('.crosshair-x'),yLine=svg.querySelector('.crosshair-y'),field=name=>tooltip.querySelector(`[data-field="${name}"]`);
  const hide=()=>{tooltip.hidden=true;svg.querySelector('.chart-crosshair').classList.remove('visible')};
  const show=event=>{const bounds=svg.getBoundingClientRect(),pointX=Math.max(0,Math.min(bounds.width,event.clientX-bounds.left)),viewX=pointX*720/bounds.width,candle=candles.reduce((nearest,item)=>Math.abs(Number(item.dataset.x)-viewX)<Math.abs(Number(nearest.dataset.x)-viewX)?item:nearest),priceY=Math.max(18,Math.min(284,(event.clientY-bounds.top)*350/bounds.height));
    xLine.setAttribute('x1',candle.dataset.x);xLine.setAttribute('x2',candle.dataset.x);yLine.setAttribute('y1',priceY);yLine.setAttribute('y2',priceY);svg.querySelector('.chart-crosshair').classList.add('visible');
    const timestamp=Number(candle.dataset.time),date=Number.isFinite(timestamp)?new Date(timestamp<1e12?timestamp*1000:timestamp):new Date(candle.dataset.time);field('time').textContent=Number.isNaN(date.getTime())?candle.dataset.time:date.toLocaleString();['open','high','low','close'].forEach(name=>field(name).textContent=`${price(candle.dataset[name])}${tooltip.dataset.quote?' '+tooltip.dataset.quote:''}`);field('volume').textContent=candle.dataset.volume===''&&routeMarket()==='forex'?'Volume not reported':number(candle.dataset.volume);
    tooltip.hidden=false;const tip=tooltip.getBoundingClientRect(),stageBox=stage.getBoundingClientRect(),gap=12;let left=event.clientX-stageBox.left+gap,top=event.clientY-stageBox.top+gap;if(left+tip.width>stageBox.width-gap)left=event.clientX-stageBox.left-tip.width-gap;if(top+tip.height>stageBox.height-gap)top=stageBox.height-tip.height-gap;tooltip.style.left=`${Math.max(gap,Math.min(left,stageBox.width-tip.width-gap))}px`;tooltip.style.top=`${Math.max(gap,Math.min(top,stageBox.height-tip.height-gap))}px`;
  };
  stage.addEventListener('pointermove',show);stage.addEventListener('pointerdown',show);stage.addEventListener('pointerleave',event=>{if(event.pointerType!=='touch')hide()});
}
function bindChartTimeframes(container,data){
  mountLightweightChart(container,data,container.querySelector('.price-chart')?.dataset.activeFrame);
  container.querySelectorAll('[data-chart-frame]:not(:disabled)').forEach(button=>button.onclick=()=>{container._chartCleanup?.();container.innerHTML=priceChart(data,button.dataset.chartFrame);bindChartTimeframes(container,data)})
}

function signalPanel(data,label){const side=data.signal.side,plan=data.risk_plan||{},holding=plan.has_active_trade_setup===false||['HOLD','WATCH','AVOID'].includes(String(side).toUpperCase());const market=location.pathname.split('/')[2]||'';const quote=market.startsWith('crypto_')?'USDT':market==='forex'?data.symbol.slice(3):market==='indian_indices'||data.symbol.endsWith('.NS')?'INR':'USD';const marketData=data.market||{};const liveTitle=market.startsWith('crypto_')?data.symbol.replace(/USDT$/,'/USDT')+' live price':data.display_name+' live price';const updated=data.last_updated?new Date(data.last_updated).toLocaleString():'—';const metrics=holding?[['Trade plan','No new trade'],['Stop loss','Not applicable for HOLD'],['Take profit','Not applicable for HOLD'],['Position size','0.0%'],['Risk score',plan.risk_score==null?'Not available':Math.round(plan.risk_score*100)+'/100']]:[['Stop loss',price(plan.stop_loss,market,data.symbol)],['Take profit',price(plan.take_profit,market,data.symbol)],['Position size',(plan.position_size_pct*100).toFixed(1)+'%'],['Risk score',plan.risk_score==null?'Not available':Math.round(plan.risk_score*100)+'/100']];return `<section class="detail-grid signal-price-grid"><article class="panel signal-card"><p class="eyebrow">${label}</p><div class="decision ${side.includes('BUY')?'positive':side.includes('SELL')?'negative':''}">${safe(side)}</div>${holding?'<p class="warning"><b>No active trade setup</b><br>HOLD means the app does not see a strong enough setup to open a new trade right now.</p>':''}<div class="live-price"><small>${safe(liveTitle)}</small><strong>${price(data.live_price??marketData.price,market,data.symbol)} <em>${quote}</em></strong><div><span class="${(data.change_24h??marketData.change_24h)>=0?'positive':'negative'}">24h ${pct(data.change_24h??marketData.change_24h)}</span><span>${reportedVolume(data.volume??marketData.volume,market)}</span></div><p>Source: ${safe(data.source||marketData.source)} · Last updated: ${safe(updated)}</p></div><p>Confidence ${Math.round(data.signal.confidence*100)}%</p><div class="confidence-bar"><span style="width:${Math.round(data.signal.confidence*100)}%"></span></div>${metrics.map(x=>`<p><b>${x[0]}:</b> ${x[1]}</p>`).join('')}</article><article class="panel chart-card"><div class="chart-mount">${priceChart(data)}</div></article></section><section class="panel reasoning-panel"><p class="eyebrow">PLAIN-LANGUAGE REASONING</p><div class="plain-copy">${safe(data.plain_language_reason||data.signal.rationale)}</div></section>`}

function technicalPanels(data){const rows=data.timeframe_breakdown||[],levels=data.key_levels||{},plan=data.risk_plan||{},holding=plan.has_active_trade_setup===false||['HOLD','WATCH','AVOID'].includes(String(data.signal?.side).toUpperCase());const planLevels=holding?`<div><small>Trade plan</small><strong>No active trade setup</strong></div><div><small>Watch above</small><strong>${plan.breakout_level==null?'Not available':price(plan.breakout_level,routeMarket(),data.symbol)}</strong></div><div><small>Watch below</small><strong>${plan.breakdown_level==null?'Not available':price(plan.breakdown_level,routeMarket(),data.symbol)}</strong></div><div><small>Current price</small><strong>${price(data.live_price??data.market?.price,routeMarket(),data.symbol)}</strong></div>`:`<div><small>Support</small><strong>${levels.support==null?'Not available':price(levels.support,routeMarket(),data.symbol)}</strong></div><div><small>Resistance</small><strong>${levels.resistance==null?'Not available':price(levels.resistance,routeMarket(),data.symbol)}</strong></div><div><small>Stop loss</small><strong>${price(plan.stop_loss,routeMarket(),data.symbol)}</strong></div><div><small>Take profit</small><strong>${price(plan.take_profit,routeMarket(),data.symbol)}</strong></div>`;return `<section class="technical-grid"><article class="panel"><p class="eyebrow">MULTI-TIMEFRAME TECHNICALS</p>${rows.length?`<div class="table-wrap"><table class="market-table technical-table"><thead><tr><th>Timeframe</th><th>Trend</th><th>RSI</th><th>MACD</th><th>EMA bias</th><th>Score</th></tr></thead><tbody>${rows.map(r=>`<tr><td><b>${safe(r.timeframe)}</b></td><td class="${r.trend==='Bullish'?'positive':r.trend==='Bearish'?'negative':''}">${safe(r.trend)}</td><td>${number(r.rsi)}</td><td>${safe(r.macd)}</td><td>${number(r.ema_bias)}</td><td>${number(r.score)}</td></tr>`).join('')}</tbody></table></div>`:'<p class="warning">Candle history is temporarily unavailable. The signal safely fell back to live-price rules.</p>'}</article><article class="panel"><p class="eyebrow">KEY LEVELS &amp; RISK PLAN</p><div class="level-grid">${planLevels}</div></article></section><section class="panel why-panel"><p class="eyebrow">WHY THIS SIGNAL?</p><h2>${safe(data.trend_summary||'')}</h2><p>${safe(data.momentum_summary||'')}</p><p>${safe(data.volatility_summary||'')}</p><p class="plain-copy">${safe(data.plain_language_reason||data.signal.rationale)}</p></section>`}

function paperTradeCopy(market,action){
  const normalized=String(action||'HOLD').toUpperCase();
  if(['HOLD','WATCH','AVOID'].includes(normalized))return {active:false,button:'Add to watchlist',helper:'No active trade setup',side:null};
  if(market==='banknifty_options'){
    if(normalized==='BUY CE')return {active:true,button:'Buy paper Call option / Buy CE',helper:'Simulates buying a Call option (CE).',side:'LONG'};
    if(normalized==='BUY PE')return {active:true,button:'Buy paper Put option / Buy PE',helper:'Simulates buying a Put option (PE).',side:'LONG'};
    return {active:false,button:'Add to watchlist',helper:'No active trade setup',side:null};
  }
  const bullish=normalized.includes('BUY'),side=bullish?'LONG':'SHORT';
  const copy={
    crypto_futures:bullish?['Open paper LONG','LONG = betting the futures price goes up.']:['Open paper SHORT','SHORT = betting the futures price goes down.'],
    crypto_spot:bullish?['Buy spot paper trade','Simulates buying the coin in spot.']:['Simulate bearish paper trade','Spot selling normally requires already owning the asset. This paper trade simulates downside exposure only.'],
    equities:bullish?['Buy paper shares','Simulates buying shares.']:['Simulate paper short','Real stock shorting may require margin/borrowing. This is only a paper simulation.'],
    indian_indices:bullish?['Buy paper shares','Simulates buying shares.']:['Simulate paper short','Real stock shorting may require margin/borrowing. This is only a paper simulation.'],
    commodities:bullish?['Open paper futures LONG','Simulates a bullish commodity futures view.']:['Open paper futures SHORT','Simulates a bearish commodity futures view.'],
    // The base currency is the first currency in the pair.
    forex:bullish?['Buy base currency paper trade','In forex, the first currency is the base currency and the second is the quote currency.']:['Sell base currency paper trade','In forex, the first currency is the base currency and the second is the quote currency.']
  }[market]||[bullish?'Bullish paper trade':'Bearish paper trade',bullish?'Simulates upside exposure.':'Simulates downside exposure.'];
  return {active:true,button:copy[0],helper:copy[1],side};
}

function paperActions(data,market,symbol){const copy=paperTradeCopy(market,data.signal.side);return `<section class="panel paper-actions"><div><p class="eyebrow">PAPER TRADING ONLY</p><h2>${copy.active?'Practise this setup — no real money is used':'Watch for a setup'}</h2><p>${copy.active?safe(copy.helper):'<b>No active trade setup — watch support/resistance for confirmation.</b>'}</p></div><div class="deep-actions"><button id="watch-asset" class="ghost">Add to watchlist</button>${copy.active?`<button id="open-paper" class="primary">${safe(copy.button)}</button>`:''}<a class="ghost" href="/paper" data-link>View paper positions</a></div><div id="paper-confirm"></div></section>`}

function bindPaperActions(data,market,symbol){const watch=document.getElementById('watch-asset');watch.onclick=async()=>{if(watch.disabled)return;watch.disabled=true;try{await postJSON('/api/paper/watchlist',{market,symbol,display_name:data.display_name});watch.textContent='Added to watchlist ✓'}catch(error){watch.disabled=false;paperInlineError(document.getElementById('paper-confirm'),error)}};const button=document.getElementById('open-paper');if(!button)return;button.onclick=()=>{const plan=data.risk_plan||{},copy=paperTradeCopy(market,data.signal.side),side=copy.side,suggested=100000*Number(plan.position_size_pct||.01),confidence=data.signal.confidence;document.getElementById('paper-confirm').innerHTML=`<div class="paper-confirm"><h3>${safe(copy.button)} — ${safe(data.display_name||displaySymbol(symbol))}</h3><p class="source-note">Internal simulation side: ${safe(side)}</p><p><b>Entry price:</b> ${price(data.live_price,market,symbol)} · <b>Stop loss:</b> ${price(plan.stop_loss,market,symbol)} · <b>Take profit:</b> ${price(plan.take_profit,market,symbol)}</p><p><b>Risk score:</b> ${plan.risk_score==null?'—':Math.round(plan.risk_score*100)+'/100'} · <b>Confidence:</b> ${confidence==null?'—':Math.round(confidence*100)+'%'}</p><label>Paper notional <input id="paper-notional" type="number" min="0.01" step="0.01" value="${suggested.toFixed(2)}"></label><p id="estimated-quantity">Estimated quantity: ${number(suggested/data.live_price)}</p><button id="confirm-paper" class="primary">Confirm paper trade</button><p class="source-note"><b>Paper trading only. No real money is used.</b></p></div>`;const input=document.getElementById('paper-notional');input.oninput=()=>document.getElementById('estimated-quantity').textContent=`Estimated quantity: ${number(Number(input.value)/data.live_price)}`;const confirm=document.getElementById('confirm-paper');confirm.onclick=async()=>{if(confirm.disabled)return;confirm.disabled=true;confirm.textContent='Opening paper trade…';try{await postJSON('/api/paper/positions',{market,symbol,side,notional_amount:Number(input.value)});navigate('/paper')}catch(error){confirm.disabled=false;confirm.textContent='Confirm paper trade';paperInlineError(document.getElementById('paper-confirm'),error)}}}}

