async function runDeep(market,symbol,refresh=false){
  const key=`${market}:${symbol.toUpperCase()}`,button=document.getElementById('deep-button');
  button.disabled=true;
  try{let jobId=deepJobKeys.get(key)||sessionStorage.getItem(`deep-job:${key}`);if(!jobId||refresh){const job=await getJSON('/api/analyze/deep',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({market,venue:venueFor(market),symbol,equity:100000,refresh})});jobId=job.job_id;deepJobKeys.set(key,jobId);sessionStorage.setItem(`deep-job:${key}`,jobId);await handleDeepStatus(job,market,symbol,key);if(['queued','running'].includes(job.status))pollDeep(jobId,market,symbol,key,Date.now());return}await pollDeep(jobId,market,symbol,key,Date.now())}catch(error){document.getElementById('deep-status').innerHTML=`<p class="ai-error"><b>Advanced Research error:</b> ${safe(error.message)} Quick Signal remains available above.</p>`;button.disabled=false}
}

async function pollDeep(jobId,market,symbol,key,waitStarted){
  const job=await getJSON(`/api/analyze/deep/status/${encodeURIComponent(jobId)}`);await handleDeepStatus(job,market,symbol,key);
  if(['queued','running'].includes(job.status)){if(Date.now()-waitStarted>=95000){showBackgroundWait(jobId,market,symbol,key);return}setTimeout(()=>pollDeep(jobId,market,symbol,key,waitStarted).catch(error=>showPollError(error,jobId,market,symbol,key)),2000)}
}

function runningMarkup(job){return `<div class="research-running"><div class="spinner"></div><div><p><b>${safe(job.progress_message)}</b></p><p>Step ${job.progress_step||1} of 5 · ${number(job.elapsed_seconds)}s elapsed</p><p>You can keep using Quick Signal while Advanced Research runs.</p></div></div>`}

function deepInsight(data){
  const deep=data.signal||{},quick=data.quick_signal?.signal||{},deepSide=String(deep.side||'—').toUpperCase(),quickSide=String(quick.side||'—').toUpperCase(),agrees=deepSide===quickSide;
  const confidence=deep.confidence==null?'Not provided':`${Math.round(deep.confidence*100)}%`,reason=data.plain_language_reason||deep.rationale||'No additional reasoning was provided.';
  const riskNotes=data.risk_notes||`Risk score ${deep.risk_score==null?'not provided':Math.round(deep.risk_score*100)+'/100'}${deep.stop_loss==null?'':` · Stop ${number(deep.stop_loss)}`}${deep.take_profit==null?'':` · Target ${number(deep.take_profit)}`}`;
  const watch=data.what_to_watch_next||'Watch the main chart’s support, resistance, momentum, and volume for confirmation before acting.';
  return `<article class="deep-insight"><div class="deep-comparison ${agrees?'agrees':'differs'}"><strong>Advanced Research ${agrees?'agrees with':'differs from'} Quick Signal</strong>${agrees?'':`<span>Quick Signal: <b>${safe(quickSide)}</b> · Advanced Research: <b>${safe(deepSide)}</b></span>`}</div><div class="deep-decision"><div><small>Advanced Research decision</small><strong class="decision ${deepSide.includes('BUY')?'positive':deepSide.includes('SELL')?'negative':''}">${safe(deepSide)}</strong></div><div><small>Confidence</small><strong>${safe(confidence)}</strong></div></div>${!agrees?`<section><h3>Reason for difference</h3><p>${safe(data.difference_reason||reason)}</p></section>`:''}<section><h3>Advanced Research reasoning</h3><p class="plain-copy">${safe(reason)}</p></section><div class="deep-notes"><section><h3>Risk notes</h3><p>${safe(riskNotes)}</p></section><section><h3>What to watch next</h3><p>${safe(watch)}</p></section></div></article>`;
}

async function handleDeepStatus(job,market,symbol,key){const status=document.getElementById('deep-status'),button=document.getElementById('deep-button');if(['queued','running'].includes(job.status)){status.innerHTML=runningMarkup(job);button.textContent='Check Advanced Research status';button.disabled=false;button.onclick=()=>pollDeep(job.job_id,market,symbol,key,Date.now());return}if(job.status==='completed'){const data=job.result;status.innerHTML=`<div class="deep-meta">Advanced Research completed${job.cached?' · cached':''} <button id="refresh-deep" class="ghost">Refresh Advanced Research</button></div>`;document.getElementById('deep-result').innerHTML=deepInsight(data);button.textContent='Refresh Advanced Research';button.disabled=false;button.onclick=()=>runDeep(market,symbol,true);document.getElementById('refresh-deep').onclick=()=>runDeep(market,symbol,true);return}const fallback=job.fallback_result;status.innerHTML=`<p class="ai-error">${safe(job.user_friendly_error)}</p><button id="restart-deep" class="ghost">Start new Advanced Research run</button>`;if(fallback){document.getElementById('deep-result').innerHTML='<p class="background-notice"><b>Advanced Research fallback used.</b> The main Quick Signal above remains the source of this result.</p>'}button.textContent='Start new Advanced Research run';button.disabled=false;button.onclick=()=>runDeep(market,symbol,true);document.getElementById('restart-deep').onclick=()=>runDeep(market,symbol,true)}

function showBackgroundWait(jobId,market,symbol,key){const status=document.getElementById('deep-status'),button=document.getElementById('deep-button');status.innerHTML='<p class="background-notice">Advanced Deep Research is still running in the background. Quick Signal remains available.</p><div class="deep-actions"><button id="check-deep" class="ghost">Check status</button><button id="continue-deep" class="ghost">Continue waiting</button><button id="fallback-deep" class="ghost">Use Quick Signal fallback</button></div>';button.textContent='Check Advanced Research status';button.disabled=false;button.onclick=()=>pollDeep(jobId,market,symbol,key,Date.now());document.getElementById('check-deep').onclick=button.onclick;document.getElementById('continue-deep').onclick=()=>pollDeep(jobId,market,symbol,key,Date.now());document.getElementById('fallback-deep').onclick=()=>{status.innerHTML='<p class="background-notice">Quick Signal remains available above. Advanced Research continues in the background.</p>'}}
function showPollError(error,jobId,market,symbol,key){document.getElementById('deep-status').innerHTML=`<p class="ai-error">Could not check Advanced Research status: ${safe(error.message)}</p><button id="check-deep" class="ghost">Check status</button>`;document.getElementById('check-deep').onclick=()=>pollDeep(jobId,market,symbol,key,Date.now())}

async function loadOptions(symbol){const target=document.getElementById('options-chain');try{const d=await getJSON(`/api/options/${encodeURIComponent(symbol)}`);const fields=[['Put/Call Ratio',d.put_call_ratio],['Max Pain',d.max_pain]].filter(x=>x[1]!=null);const columns=[['option_type','Type'],['strike','Strike'],['open_interest','Open Interest'],['iv','IV'],['delta','Delta'],['gamma','Gamma'],['theta','Theta'],['vega','Vega']].filter(([key])=>d.contracts.some(r=>r[key]!=null&&r[key]!==''));target.innerHTML=`<p class="eyebrow">OPENBB OPTION CHAIN</p><div>${fields.map(x=>`<b>${x[0]}:</b> ${number(x[1])} `).join('')}</div>${d.expiries.length?`<label>Expiry <select id="expiry">${d.expiries.map(x=>`<option>${safe(x)}</option>`).join('')}</select></label>`:''}${d.strikes.length?`<label>Strike <select>${d.strikes.map(x=>`<option>${number(x)}</option>`).join('')}</select></label>`:''}<div class="table-wrap"><table class="market-table"><thead><tr>${columns.map(x=>`<th>${x[1]}</th>`).join('')}</tr></thead><tbody>${d.contracts.map(r=>`<tr>${columns.map(([key])=>`<td>${key==='option_type'?safe(r[key]):number(r[key])}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}catch(e){target.remove()}}

function bankOptionRows(rows){return rows.map(r=>`<tr><td><b>${safe(r.option_type)}</b></td><td>${number(r.strike)}</td><td>${safe(r.moneyness)}</td><td>${number(r.last_price)}</td><td class="${r.change>=0?'positive':'negative'}">${pct(r.change)}</td><td>${number(r.volume)}</td><td>${number(r.open_interest)}</td><td>${number(r.implied_volatility)}</td><td>${number(r.bid)} / ${number(r.ask)}</td><td><b>${safe(r.score.signal)}</b><br><small>${Math.round(r.score.confidence*100)}% · risk ${r.score.risk_score}</small></td></tr>`).join('')}

async function bankNiftyOptionsPage(){
  app.innerHTML='<div class="loading-page"><div class="spinner"></div><p>Loading the real Bank Nifty option chain…</p></div>';
  try{const data=await getJSON('/api/banknifty-options');if(!data.available){const state=data.provider_status==='not_configured'?'Not configured':'Provider temporarily unavailable';app.innerHTML=`<a class="back" href="/" data-link>← All markets</a>${pageHeader('RESEARCH ONLY','Bank Nifty Options','CE/PE strikes, expiry, OI and option signals')}<section class="provider-unavailable panel"><div class="status-badges"><span>${state}</span><span>Research only</span><span>No fake rows shown</span></div><p class="eyebrow">OPTION CHAIN</p><h2>Live option-chain provider required</h2><p>Real Bank Nifty option rows could not be retrieved right now.</p><p>No fake rows are generated.</p><details class="provider-setup"><summary>Connect live options provider</summary><p>Configure an option-chain capable OpenBB service, then retry. The connection is marked live only after valid contracts are returned.</p></details><div class="import-placeholder"><div><b>Import option-chain CSV for demo/research</b><small>Imported data would be clearly labelled as non-live.</small></div><button class="ghost" type="button" disabled title="CSV import is coming in a later update">Coming soon</button></div>${data.provider_diagnostics?`<details class="provider-attempts"><summary>Provider diagnostics</summary>${data.provider_diagnostics.map(d=>`<p><b>${safe(d.provider)}:</b> ${d.attempted?'attempted':'not attempted'} · ${safe(d.failure_category||'connected')} · HTTP ${safe(d.status_code??'n/a')} · rows ${safe(d.normalized_contract_count??0)}${d.sanitized_error?` · ${safe(d.sanitized_error)}`:''}</p>`).join('')}</details>`:''}<p class="warning"><b>Research only.</b> No live options order placement is available, and no option rows are fabricated.</p><button id="retry-banknifty" class="primary">Retry live provider</button></section>`;document.getElementById('retry-banknifty').onclick=bankNiftyOptionsPage;return}
    app.innerHTML=`<a class="back" href="/" data-link>← All markets</a>${pageHeader('RESEARCH ONLY','Bank Nifty Options','CE/PE strikes, expiry, OI and option signals')}<section class="option-reference panel"><div><small>BANK NIFTY live reference price</small><strong>${number(data.underlying_price)}</strong></div><div><small>ATM strike</small><strong>${number(data.atm_strike)}</strong></div><label>Expiry <select id="option-expiry"><option value="">All</option>${data.expiries.map(x=>`<option value="${safe(x)}">${safe(x)}</option>`).join('')}</select></label></section><div class="option-filters" id="option-types">${['ALL','CE','PE'].map(x=>`<button class="ghost${x==='ALL'?' active':''}" data-filter="${x}">${x}</button>`).join('')}</div><div class="option-filters" id="option-money">${['ALL','ITM','ATM','OTM'].map(x=>`<button class="ghost${x==='ALL'?' active':''}" data-filter="${x}">${x}</button>`).join('')}</div><div class="table-wrap"><table class="market-table"><thead><tr><th>Type</th><th>Strike</th><th>Moneyness</th><th>Last</th><th>Change</th><th>Volume</th><th>Open interest</th><th>IV</th><th>Bid / Ask</th><th>Option signal</th></tr></thead><tbody id="bank-option-body">${bankOptionRows(data.contracts)}</tbody></table></div><p class="source-note">Source: ${safe(data.source)} · Research only · No live options order placement.</p>`;
    let typeFilter='ALL',moneyFilter='ALL';const draw=()=>{const expiry=document.getElementById('option-expiry').value;document.getElementById('bank-option-body').innerHTML=bankOptionRows(data.contracts.filter(r=>(!expiry||r.expiry===expiry)&&(typeFilter==='ALL'||r.option_type===typeFilter)&&(moneyFilter==='ALL'||r.moneyness===moneyFilter)))};document.getElementById('option-expiry').addEventListener('change',draw);[['option-types','type'],['option-money','money']].forEach(([id,kind])=>document.getElementById(id).addEventListener('click',e=>{if(!e.target.dataset.filter)return;if(kind==='type')typeFilter=e.target.dataset.filter;else moneyFilter=e.target.dataset.filter;document.querySelectorAll(`#${id} button`).forEach(b=>b.classList.toggle('active',b.dataset.filter===e.target.dataset.filter));draw()}))
  }catch(error){errorView(error)}
}

async function paperPage(){app.innerHTML='<div class="loading-page"><div class="spinner"></div><p>Loading your paper portfolio…</p></div>';try{const [account,positions,trades,watchlist,journal]=await Promise.all(['/api/paper/account','/api/paper/positions','/api/paper/trades','/api/paper/watchlist','/api/paper/journal'].map(url=>getJSON(url)));const cards=[['Starting balance',account.starting_balance],['Current equity',account.equity],['Cash balance',account.cash_balance],['Realized P&L',account.realized_pnl],['Unrealized P&L',account.unrealized_pnl],['Total P&L',account.total_pnl],['Win rate',account.win_rate,'pct'],['Open positions',account.open_positions_count,'count'],['Closed trades',account.closed_trades_count,'count']];app.innerHTML=`${pageHeader('PAPER MODE','Paper Trading Dashboard','Practise trades safely. Paper trading only — no real money is used.')}<aside class="what-is-this panel"><b>Beginner guide:</b> LONG means the paper trade benefits if price rises. SHORT means it benefits if price falls. Unrealized P&amp;L is profit/loss if closed now; realized P&amp;L is profit/loss after closing.</aside><section class="account-grid">${cards.map(([label,value,type])=>`<article class="panel account-card"><small>${label}</small><strong class="${Number(value)>=0?'positive':'negative'}">${type==='pct'?pct(value):type==='count'?number(value):money(value)}</strong></article>`).join('')}</section><section class="panel"><p class="eyebrow">OPEN POSITIONS</p>${paperPositionTable(positions)}</section><section class="panel"><p class="eyebrow">CLOSED TRADES</p>${paperTradeTable(trades)}</section><section class="paper-lower"><article class="panel"><p class="eyebrow">WATCHLIST</p>${watchlist.length?watchlist.map(x=>`<div class="paper-list">${paperAssetLink(x)}<span>${safe(x.latest_action||'Not analysed')} · ${price(x.latest_price,x.market,x.symbol)} · ${x.latest_confidence==null?'—':pct(x.latest_confidence*100)}</span><button class="ghost remove-watch" data-market="${safe(x.market)}" data-symbol="${safe(x.symbol)}">Remove</button></div>`).join(''):'<p>No saved assets yet.</p>'}</article><article class="panel"><p class="eyebrow">TRADE JOURNAL</p><form id="journal-form"><label>Note <textarea id="journal-note" required maxlength="4000" placeholder="What did you learn?"></textarea></label><label>Symbol (optional) <input id="journal-symbol" maxlength="32"></label><button class="primary">Add note</button></form><div class="journal-list">${journal.slice(0,10).map(x=>`<div><b>${safe(x.symbol||'General note')}</b><p>${safe(x.note)}</p><small>${new Date(x.created_at).toLocaleString()}</small></div>`).join('')}</div></article></section>`;document.querySelectorAll('.close-paper').forEach(b=>b.onclick=async event=>{event.preventDefault();event.stopPropagation();if(b.disabled)return;b.disabled=true;try{await postJSON(`/api/paper/positions/${b.dataset.id}/close`,{close_reason:'Closed from dashboard'});paperPage()}catch(error){b.disabled=false;paperInlineError(b.closest('td'),error)}});document.querySelectorAll('.remove-watch').forEach(b=>b.onclick=async event=>{event.preventDefault();event.stopPropagation();if(b.disabled)return;b.disabled=true;try{await deleteJSON(`/api/paper/watchlist/${b.dataset.market}/${encodeURIComponent(b.dataset.symbol)}`);paperPage()}catch(error){b.disabled=false;paperInlineError(b.parentElement,error)}});document.getElementById('journal-form').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget,submit=form.querySelector('button');if(submit.disabled)return;submit.disabled=true;submit.textContent='Adding note…';try{await postJSON('/api/paper/journal',{note:document.getElementById('journal-note').value,symbol:document.getElementById('journal-symbol').value||null});paperPage()}catch(error){submit.disabled=false;submit.textContent='Add note';paperInlineError(form,error)}}}catch(error){paperErrorView(error)}}

function paperDashboardLabel(market,side){if(['equities','indian_indices'].includes(market))return side==='LONG'?'Paper shares':'Simulated paper short';if(['crypto_futures','commodities'].includes(market))return `Paper futures ${side.toLowerCase()}`;if(market==='forex')return side==='LONG'?'Buy base currency paper trade':'Sell base currency paper trade';return side==='LONG'?'Bullish paper trade':'Bearish paper trade'}
function paperPositionTable(rows){return rows.length?`<div class="table-wrap"><table class="market-table"><thead><tr><th>Asset</th><th>Paper action</th><th>Entry / Current</th><th>Quantity</th><th>P&amp;L</th><th>Stop / Target</th><th>Confidence / Risk</th><th>Opened</th><th></th></tr></thead><tbody>${rows.map(x=>`<tr><td>${paperAssetLink(x)}</td><td>${safe(paperDashboardLabel(x.market,x.side))}<br><small>Internal side: ${safe(x.side)}</small></td><td>${price(x.entry_price,x.market,x.symbol)} / ${price(x.current_price,x.market,x.symbol)}</td><td>${quantity(x.quantity)}</td><td class="${x.unrealized_pnl>=0?'positive':'negative'}">${money(x.unrealized_pnl)} (${pct(x.unrealized_pnl_pct)})</td><td>${price(x.stop_loss,x.market,x.symbol)} / ${price(x.take_profit,x.market,x.symbol)}</td><td>${x.confidence==null?'—':pct(x.confidence*100)} / ${x.risk_score==null?'—':Math.round(x.risk_score*100)}</td><td>${new Date(x.opened_at).toLocaleString()}</td><td><button class="ghost close-paper" data-id="${x.id}">Close</button></td></tr>`).join('')}</tbody></table></div>`:'<p>No open paper positions.</p>'}
function paperTradeTable(rows){return rows.length?`<div class="table-wrap"><table class="market-table"><thead><tr><th>Asset</th><th>Paper action</th><th>Entry / Exit</th><th>Realized P&amp;L</th><th>Result</th><th>Reason</th><th>Opened / Closed</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${paperAssetLink(x)}</td><td>${safe(paperDashboardLabel(x.market,x.side))}<br><small>Internal side: ${safe(x.side)}</small></td><td>${price(x.entry_price,x.market,x.symbol)} / ${price(x.exit_price,x.market,x.symbol)}</td><td class="${x.realized_pnl>=0?'positive':'negative'}">${money(x.realized_pnl)} (${pct(x.realized_pnl_pct)})</td><td>${safe(x.result)}</td><td>${safe(x.close_reason)}</td><td>${new Date(x.opened_at).toLocaleString()} / ${new Date(x.closed_at).toLocaleString()}</td></tr>`).join('')}</tbody></table></div>`:'<p>No closed paper trades yet.</p>'}

function render(){const parts=location.pathname.split('/').filter(Boolean);if(!parts.length)return home();if(parts[0]==='paper')return paperPage();if(parts[0]==='market'&&parts[1]==='banknifty_options')return bankNiftyOptionsPage();if(parts[0]==='market'&&parts[1])return marketPage(parts[1]);if(parts[0]==='scores'&&parts[1])return scoresPage(parts[1]);if(parts[0]==='asset'&&parts[1]&&parts[2])return assetPage(parts[1],decodeURIComponent(parts.slice(2).join('/')));return home();}

let installPrompt;window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e});document.getElementById('install').addEventListener('click',async()=>{if(installPrompt){installPrompt.prompt();await installPrompt.userChoice;installPrompt=null}else alert('In Chrome, open the menu and choose “Cast, save and share” → “Install page as app”.')});if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js');render();
